  assign \event_stream__payload.phase  = event_stream__payload[15:0];
  assign \event_stream__payload.cycle  = event_stream__payload[39:16];
  assign \event_stream__payload.bin  = event_stream__payload[50:40];
  assign \event_stream__payload.read  = event_stream__payload[52:51];
endmodule
